@Bean
@Primary
DataSource dataSource(
        @Qualifier("writeDataSource") DataSource writeDataSource,
        @Qualifier("readDataSource") DataSource readDataSource) {
    LazyConnectionDataSourceProxy proxy =
            new LazyConnectionDataSourceProxy(writeDataSource);

    proxy.setReadOnlyDataSource(readDataSource);
    return proxy;
}

@Service
@RequiredArgsConstructor
@Transactional(readOnly = true)
public class NotificationQueryService {
    private final NotificationRepository notificationRepository;

    public int countUnread(Integer userId) {
        return Math.toIntExact(
                notificationRepository
                        .countByUserIdAndReadFalseAndDeletedFalse(userId));
    }
}

@Transactional
public ReviewResponse reply(
        Integer userId,
        Integer reviewId,
        String reply
) {
    Review review = reviewRepository
            .findByIdAndDeletedFalse(reviewId)
            .orElseThrow();

    review.reply(reply);
    return reviewQueryService.toResponse(review);
}
